<?php

namespace App\Enums;

enum MessageType: string
{
    /** A normal, user-authored message. */
    case Text = 'text';

    /** A user-authored message whose primary payload is its attachments. */
    case File = 'file';

    /** Generated by Snack itself, e.g. "Ada joined the channel". */
    case System = 'system';

    /** Posted to an announcement channel by an admin. */
    case Announcement = 'announcement';

    public function label(): string
    {
        return match ($this) {
            self::Text => 'Message',
            self::File => 'File',
            self::System => 'System',
            self::Announcement => 'Announcement',
        };
    }

    /**
     * System messages are never editable, deletable, or reactable by users.
     */
    public function isAuthoredByUser(): bool
    {
        return $this !== self::System;
    }

    /**
     * @return array<int, string>
     */
    public static function values(): array
    {
        return array_column(self::cases(), 'value');
    }
}
